args:
L="tadu list --limit 0"; s() { sed -E "s/^[^:]*:(t-[0-9a-f]+) \[[a-z_]+\] [a-z-]+ (due [0-9-]+ )?/- \1 /"; }
{ echo "## T1"; $L --open --min-priority high | s; echo; echo "## T2"; $L --open --due-before 2026-11-23 | s; echo;
  echo "## T3"; $L --open --category ui | s; echo; echo "## T4"; $L --open --type bug | s; echo;
  echo "## T5"; $L --open --category ui --type bug --min-priority high | s; echo; echo "## T6"; $L --open --column blocked | s; echo;
  echo "## T7"; $L --open --label csv-import | s; echo;
  echo "## T8"; $L --history --include-cancelled --label csv-import | grep -E "\[(done|cancelled)\]" | s; echo;
  echo "## T9"; $L --open --due-before 2026-11-16 | s; } > ANSWERS.md; grep -c "^- t-" ANSWERS.md; sed -n 1,3p ANSWERS.md
